        /** @enum {string} */
        EndpointJobStatus: "queued" | "running" | "succeeded" | "failed" | "timed-out" | "cancelled" | "offline";
        /** @enum {string} */
        Severity: "critical" | "high" | "medium" | "low";
        /** @enum {string} */
        PlatformFamily: "windows" | "macos" | "linux" | "aix";
        /** @enum {string} */
        Framework: "cis" | "stig" | "pci-dss" | "hipaa";
        /** @enum {string} */
        ExportFormat: "csv" | "xlsx" | "pdf" | "html";
